import{_ as a,o as s,c as o,ag as i}from"./chunks/framework.DoUXNnsN.js";const C=JSON.parse('{"title":"OPC-DA","description":"","frontmatter":{"title":"OPC-DA","aliases":["OPC DA","OPC Data Access","经典OPC","OPC Classic","OLE for Process Control"],"tags":["工业通信","OPC"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Open_Platform_Communications","https://opcfoundation.org/about/opc-technologies/opc-classic/","https://support.microsoft.com/ro-RO/servicing/os/windows/2021/06/kb5004442-manage-changes-for-windows-dcom-server-security-feature-bypass-cve-2021-26414","https://support.seeq.com/kb/latest/cloud/dcom-hardening","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":10},"headers":[],"relativePath":"70-工业通信与自动化/OPC-DA.md","filePath":"70-工业通信与自动化/OPC-DA.md"}'),e={name:"70-工业通信与自动化/OPC-DA.md"};function n(r,t,l,d,p,c){return s(),o("div",null,[...t[0]||(t[0]=[i(`<blockquote class="callout-warn"><p>⚠ 待核对：OPC DA 规范的具体版本号（常见的是 2.05a 与 3.0）、DCOM 加固（KB5004442）的强制时间点，我只在二手资料里查到，未在微软官方页面的正文里逐条核实。OPC 服务器本身（COM/DCOM 组件）<strong>⚠ 未在本机运行验证</strong>：本机没有装任何 OPC DA 服务器，下面只验证了&quot;COM 是什么&quot;这一层。</p></blockquote><blockquote><p>本篇属于 <a href="/Encyclopedia/70-工业通信与自动化/工业通信">工业通信</a> 系列，是 <a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a> 的&quot;前传&quot;。读完你应该能：说出 OPC DA 的数据模型（服务器 / 组 / 项）；理解它为什么依赖 COM/DCOM，以及这带来的麻烦；知道现场遇到老 OPC DA 服务器时怎么办（网关、包装器）。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>OPC DA（Data Access，数据访问）是<strong>经典 OPC（OPC Classic）<strong>里最常用的规范：用微软的 <strong>COM/DCOM</strong> 技术，让上位机软件以统一的方式读写 PLC、仪表等设备的</strong>实时数据</strong>。OPC 最初的名字是 OLE for Process Control（用于过程控制的 OLE），1996 年起步。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li>知道 <a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a> 把数据放在内部变量里，需要一个&quot;驱动&quot;才能让上位机读到（见 <a href="/Encyclopedia/70-工业通信与自动化/工业通信">工业通信</a>）。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a> 基础：DCOM 通过网络远程调用，端口和防火墙配置是痛点。</li><li>看过 <a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a> 会更容易理解&quot;为什么需要新一代&quot;。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>20 世纪 90 年代，每个组态软件（上位机）要为每个品牌的 PLC 各写一个驱动：N 个软件 x M 种设备 = N x M 个驱动。OPC 规定：</p><ul><li><strong>设备厂商（或第三方）只写一个 OPC 服务器</strong>，把自家设备的数据按统一接口暴露；</li><li><strong>上位机只写一个 OPC 客户端</strong>，就能连任何 OPC 服务器。</li></ul><p>驱动数量从 N x M 降到 N + M。这在当年是巨大的进步，因此 OPC DA 至今仍在大量老工厂里使用。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="com-与-dcom-opc-da-的地基" tabindex="-1">COM 与 DCOM：OPC DA 的地基 <a class="header-anchor" href="#com-与-dcom-opc-da-的地基" aria-label="Permalink to &quot;COM 与 DCOM：OPC DA 的地基&quot;">​</a></h3><p><strong>COM（Component Object Model）</strong> 是 Windows 的组件技术：一个程序（组件）注册后，别的程序可以按&quot;名字&quot;创建它并调用其接口，不用关心它是谁写的。<strong>DCOM</strong> 是 COM 的远程版本：客户端在电脑 A，服务器在电脑 B，调用通过网络转发。</p><p>在本机我实际验证了 COM 的基本动作（PowerShell，使用 Windows 自带的 <code>Scripting.Dictionary</code> 组件）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> New-Object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ComObject Scripting.Dictionary      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 按名字 ProgID 创建 COM 对象</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$d.Add(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OvenTemp&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 240.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); $d.Add(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OvenSetpoint&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 240</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Count = &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $d.Count</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OvenTemp = &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $d.Item(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OvenTemp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ItemProperty</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Registry::HKEY_CLASSES_ROOT\\Scripting.Dictionary\\CLSID&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;(default)&#39;</span></span></code></pre></div><p>实际输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Count = 2</span></span>
<span class="line"><span>OvenTemp = 240.5</span></span>
<span class="line"><span>{EE09B103-97E0-11CF-978F-00A02463E06F}</span></span></code></pre></div><p>这里 <code>Scripting.Dictionary</code> 叫 <strong>ProgID</strong>（好记的名字），后面那串花括号是 <strong>CLSID</strong>（全局唯一 ID），注册表 <code>HKEY_CLASSES_ROOT</code> 里记录了&quot;这个名字对应哪个 CLSID、哪个 DLL/EXE&quot;。OPC DA 服务器也是这样注册的，例如某厂商的 ProgID 形如 <code>厂商名.OPC.Server.1</code>。客户端拿着 ProgID 就能创建服务器对象。</p><h3 id="数据模型-服务器-组-项" tabindex="-1">数据模型：服务器 -&gt; 组 -&gt; 项 <a class="header-anchor" href="#数据模型-服务器-组-项" aria-label="Permalink to &quot;数据模型：服务器 -&gt; 组 -&gt; 项&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OPC Server（服务器，一个进程/组件）</span></span>
<span class="line"><span> ├── Group &quot;烘箱&quot;（组：一批一起读、同一刷新周期的数据）</span></span>
<span class="line"><span> │    ├── Item &quot;PLC1.Oven.Temp&quot;（项：一个具体的数据点）</span></span>
<span class="line"><span> │    └── Item &quot;PLC1.Oven.Setpoint&quot;</span></span>
<span class="line"><span> └── Group &quot;贴片机&quot;</span></span>
<span class="line"><span>      └── ...</span></span></code></pre></div><ul><li><strong>Item（项）</strong>：一个数据点，用字符串 <strong>ItemID</strong> 标识（如 <code>PLC1.Oven.Temp</code>，格式由服务器厂商决定）。客户端读到的是三元组：<strong>值（Value）、质量（Quality）、时间戳（Timestamp）</strong>。</li><li><strong>Quality（质量）</strong>：一个字节，表示&quot;这个值可不可信&quot;。常见约定（基于模型知识）：<code>0xC0</code>（192）= Good，<code>0x40</code>（64）= Uncertain，<code>0x00</code> = Bad。设备断线时值会保留旧数字，但质量变成 Bad，<strong>客户端必须判断质量，不能只看值</strong>。</li><li><strong>Group（组）</strong>：客户端建立的集合，设置<strong>更新周期</strong>（如 1000 ms）和<strong>死区</strong>（变化小于多少不报）。可以同步读/写，也可以异步订阅——组内数据变化时，服务器回调客户端（这是 DA 版的&quot;订阅&quot;，对应 UA 的 Subscription）。</li></ul><p>DA 只有&quot;平面的点列表&quot;（有的服务器支持简单的层次浏览），没有 UA 那种带类型、带引用的节点图；数据<strong>没有语义</strong>，ItemID 的含义要靠文档。</p><p>经典 OPC 家族还有 <strong>HDA</strong>（Historical Data Access，历史数据）、<strong>A&amp;E</strong>（Alarms and Events，报警与事件），它们同样基于 COM。</p><h2 id="为什么被-ua-取代" tabindex="-1">为什么被 UA 取代 <a class="header-anchor" href="#为什么被-ua-取代" aria-label="Permalink to &quot;为什么被 UA 取代&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>OPC DA（经典）</th><th>OPC UA</th></tr></thead><tbody><tr><td>平台</td><td>只能 Windows（COM/DCOM）</td><td>Windows / Linux / 嵌入式，Java、.NET、C 都能实现</td></tr><tr><td>网络</td><td>DCOM 用动态端口，穿防火墙、跨域、跨 NAT 都困难</td><td>单个固定端口（4840），防火墙好配</td></tr><tr><td>安全</td><td>依赖 Windows 的 DCOM 权限和账号，配置繁琐；还因为微软安全加固而不断出兼容问题</td><td>内置证书、签名、加密、用户认证</td></tr><tr><td>数据模型</td><td>平面点表，无类型和语义</td><td>节点图、类型、配套规范</td></tr><tr><td>稳定性</td><td>版本、组件注册容易冲突</td><td>标准二进制协议，规范完整</td></tr></tbody></table><p><strong>DCOM 加固</strong>：微软为修复 CVE-2021-26414 安全漏洞，分阶段提高了 DCOM 激活时的最低认证级别（要求&quot;数据包完整性&quot;级别），按二手资料的说法，2021 年 6 月默认关闭，2022 年 6 月默认开启，2023 年 3 月 14 日起强制、无法关闭（⚠ 具体日期待核对）。老 OPC 客户端如果用较低认证级别调用，就会连不上——这是近年老工厂 OPC DA 突然&quot;断连&quot;的常见原因。</p><h2 id="逐步例子-一个-opc-da-读数的完整过程" tabindex="-1">逐步例子：一个 OPC DA 读数的完整过程 <a class="header-anchor" href="#逐步例子-一个-opc-da-读数的完整过程" aria-label="Permalink to &quot;逐步例子：一个 OPC DA 读数的完整过程&quot;">​</a></h2><p>场景：上位机 A 想读车间 PLC 的炉温。电脑 B 装了 PLC 厂商的 OPC DA 服务器。</p><ol><li>在电脑 B 上配置 OPC 服务器：添加设备（PLC 的 IP）、添加数据点，得到 ItemID，如 <code>PLC1.Oven.Temp</code>。</li><li>在电脑 A 的 OPC 客户端里填：服务器所在主机名 B、ProgID。客户端通过 DCOM 在 B 上创建服务器对象。</li><li>客户端创建组 &quot;烘箱&quot;，更新周期 1000 ms，添加项 <code>PLC1.Oven.Temp</code>。</li><li>服务器每秒读 PLC（用它自己的底层协议，如 S7 或 Modbus），温度由 240.4 变成 240.5 时，通过回调把 <code>(240.5, Good, 08:00:01)</code> 推给客户端。</li><li>某天 PLC 网线松了：服务器收不到数据，回调给客户端的是 <code>(240.5, Bad, 08:03:00)</code>——值没变，质量变了。如果客户端只存了值，MES 报表上就会出现一条&quot;炉温 240.5 一直不变&quot;的假数据。</li></ol><p>这个例子的关键启示：<strong>读 OPC DA 时，质量和时间戳与值同样重要</strong>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>本机没有 OPC DA 服务器，且 OPC 服务器多为商业软件（需要授权或仿真版），所以：</p><ol><li><strong>验证 COM 的概念</strong>：运行上面的 PowerShell 片段，再打开注册表编辑器（<code>regedit</code>），到 <code>HKEY_CLASSES_ROOT\\CLSID\\{EE09B103-97E0-11CF-978F-00A02463E06F}\\InprocServer32</code>，会看到它指向 <code>C:\\Windows\\System32\\scrrun.dll</code>（我在本机看到的就是这个）。这就是&quot;名字 -&gt; CLSID -&gt; DLL&quot;的注册链。</li><li><strong>（⚠ 未在本机运行验证）体验真正的 OPC DA</strong>：在一台测试电脑上安装厂商提供的 OPC 仿真服务器（常见的有 Matrikon、KEPServerEX 的演示版）和一个免费 OPC 客户端，按&quot;逐步例子&quot;建组、加项，观察 Value / Quality / Timestamp 三列。这一步请严格在测试电脑上做，不要连生产设备。</li><li><strong>（⚠ 未在本机运行验证）C# 访问</strong>：C# 访问 OPC DA 通常要用第三方封装库或 OPC Foundation 提供的 COM 互操作包装，API 因库而异，这里不给出未经验证的代码。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>最可能的原因</th></tr></thead><tbody><tr><td>本机能连、远程客户端连不上</td><td>DCOM 权限（启动与激活权限、访问权限）没给远程用户；两台机器账号/密码不一致；防火墙没放行 135 端口及 DCOM 动态端口</td></tr><tr><td>更新后突然全部连不上</td><td>系统补丁的 DCOM 加固，客户端认证级别过低；升级 OPC 软件到支持新级别的版本</td></tr><tr><td>值不变、不报错</td><td>没判断 Quality；设备断线后服务器保留旧值</td></tr><tr><td>32 位客户端连不上 64 位服务器</td><td>COM 组件位数不匹配，需要对应位数的注册</td></tr><tr><td>读到的数据偏慢</td><td>组的更新周期设得太大；服务器与 PLC 之间的轮询周期瓶颈</td></tr></tbody></table><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><ul><li><strong>业务视角</strong>：很多工厂的老产线、老组态软件还靠 OPC DA。新项目首选 <a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a>，但改造老系统要考虑成本：设备停产、厂家不再提供 UA 服务器时，只能&quot;网关过渡&quot;。</li><li><strong>技术视角（网关/迁移）</strong>： <ol><li><strong>UA 包装器（Wrapper）/ 代理（Proxy）</strong>：在 DA 服务器所在电脑上装一个转换软件，把 DA 服务器&quot;包装&quot;成 UA 服务器，新客户端用 UA 连；</li><li><strong>采集网关</strong>：用 KEPServerEX 一类的软件，一端接设备，一端同时提供 DA 和 UA；</li><li><strong>直接绕过 OPC</strong>：用 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>、<a href="/Encyclopedia/70-工业通信与自动化/西门子S7通信">西门子S7通信</a> 等协议直连设备，在自己的采集服务里解析（见 <a href="/Encyclopedia/80-电子制造业务/设备自动化/设备数据采集">设备数据采集</a>）。 无论哪种，都应把 OPC 通信限制在设备网络内（见 <a href="/Encyclopedia/70-工业通信与自动化/工业网络安全">工业网络安全</a>）。</li></ol></li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>OPC DA 里一个&quot;项&quot;读出来包含哪三个信息？ <strong>答</strong>：值、质量、时间戳。</li><li>为什么 OPC DA 难以穿过防火墙？ <strong>答</strong>：DCOM 使用 135 端口加动态分配的端口，需要放行一大段端口；且依赖 Windows 账号权限，跨域、跨 NAT 复杂。UA 使用固定端口。</li><li>设备断线后，OPC DA 客户端读到的值通常是什么？ <strong>答</strong>：服务器可能仍返回最后一个旧值，但质量会变成 Bad；所以必须检查质量。</li><li>某厂只有一台老 OPC DA 服务器，MES 想用 C# 现代化接入，怎么做最稳妥？ <strong>答</strong>：优先看能否在服务器所在机器上装 DA-&gt;UA 包装器/网关，让 MES 用 OPC UA 客户端连；其次评估绕过 OPC 直连设备协议。</li><li>COM 的 ProgID 和 CLSID 分别是什么？ <strong>答</strong>：ProgID 是人类可读的名字（如 <code>Scripting.Dictionary</code>），CLSID 是全局唯一的 GUID，注册表记录了二者与实际组件文件的对应关系。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OPC DA = 基于 COM/DCOM 的实时数据访问规范，数据模型是&quot;服务器 -&gt; 组 -&gt; 项&quot;，读数含值、质量、时间戳。</li><li>它把 N x M 个驱动降为 N + M，但绑定 Windows，DCOM 配置难、穿防火墙难、安全弱。</li><li>UA 取代 DA 的原因：跨平台、固定端口、内置安全、有语义。</li><li>现场遇到老 DA：优先网关/包装器迁移到 UA；一定要判断质量位。</li><li>本篇 COM 概念已验证，OPC DA 服务器本身 ⚠ 未在本机运行验证。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a>、<a href="/Encyclopedia/70-工业通信与自动化/工业通信">工业通信</a>、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a>、<a href="/Encyclopedia/70-工业通信与自动化/SCADA">SCADA</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-TCP">Modbus-TCP</a>、<a href="/Encyclopedia/80-电子制造业务/设备自动化/设备数据采集">设备数据采集</a>、<a href="/Encyclopedia/70-工业通信与自动化/工业网络安全">工业网络安全</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>OPC Foundation 对经典 OPC 的介绍：<a href="https://opcfoundation.org/about/opc-technologies/opc-classic/" target="_blank" rel="noreferrer">https://opcfoundation.org/about/opc-technologies/opc-classic/</a></li><li>维基百科 Open Platform Communications：<a href="https://en.wikipedia.org/wiki/Open_Platform_Communications" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Open_Platform_Communications</a></li><li>微软 KB5004442（DCOM 加固，请以最新官方页面为准）：<a href="https://support.microsoft.com/ro-RO/servicing/os/windows/2021/06/kb5004442-manage-changes-for-windows-dcom-server-security-feature-bypass-cve-2021-26414" target="_blank" rel="noreferrer">https://support.microsoft.com/ro-RO/servicing/os/windows/2021/06/kb5004442-manage-changes-for-windows-dcom-server-security-feature-bypass-cve-2021-26414</a></li><li>Seeq 对 DCOM 加固时间线的说明（二手资料）：<a href="https://support.seeq.com/kb/latest/cloud/dcom-hardening" target="_blank" rel="noreferrer">https://support.seeq.com/kb/latest/cloud/dcom-hardening</a></li></ul>`,45)])])}const u=a(e,[["render",n]]);export{C as __pageData,u as default};
